"""Fixed, reviewed replies for safety situations. Never generated by an LLM.

Follows safe-messaging practice: no method details, no diagnosis, always
offer human help. Until the SOS alert service exists (Week 3) these texts
must NOT claim that a counsellor has been notified.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class Support:
    # "urgent": show the crisis card (helplines, contact counsellor) right away.
    # "suggest": gently suggest talking to someone.
    level: str
    title: str
    message: str


URGENT = Support(
    level="urgent",
    title="You're not alone",
    message=(
        "It sounds like you might be going through something really painful. "
        "You deserve support right now. Please reach out to someone you trust, "
        "your college counsellor, or a helpline below. They are free and "
        "confidential. If you are in immediate danger, call 112."
    ),
)

SUGGEST = Support(
    level="suggest",
    title="Talking can help",
    message=(
        "Your answers suggest things have been hard lately. This is a screening, "
        "not a diagnosis. Talking to your college counsellor or someone you trust "
        "can really help."
    ),
)
